await t('Board drawer: All steps for this brand',async()=>{await p.click('#drawer [data-act=nav-steps]');await p.waitForTimeout(300);return (await p.evaluate(()=>location.hash)).startsWith('#brand-')&&!!(await p.$('.ptrack'))});
await t('Board Signed square shows SOW stage picker',async()=>{await go('sow');const sq=await p.$$('tbody tr:first-child button.bd');await sq[sq.length-1].click();await p.waitForTimeout(200);const r=!!(await p.$('#drawer select[data-kind=sow]'));await closeAll();return r});
await t('SOW list row opens SOW editor',async()=>{await go('sow');await p.click('[data-act=sowview][data-v=list]');await p.click('tr[data-kind=sow] td:nth-child(3)');await p.waitForTimeout(200);const r=await drawerOpen();await closeAll();return r});
await t('Access grid square opens access editor',async()=>{await go('access');await p.click('#topbar [data-act=simple][data-v="1"]');await p.waitForTimeout(150);await p.click('button.acd[data-act=open]');await p.waitForTimeout(200);const r=await drawerOpen();await closeAll();return r});
await t('Access grid "Missing access only" filters rows',async()=>{await go('access');const a=(await p.$$('main tbody tr')).length;await p.click('[data-act=accgap][data-v="1"]');await p.waitForTimeout(150);const c=(await p.$$('main tbody tr')).length;await p.click('[data-act=accgap][data-v="0"]');return c<a});
await t('Access grid + creates a row and opens it',async()=>{await go('access');const n=(await p.$$('button.acd[data-act=open]')).length;await p.click('button.acd-empty');await p.waitForTimeout(400);const r=await drawerOpen();await closeAll();await p.waitForTimeout(150);return r&&(await p.$$('button.acd[data-act=open]')).length===n+1});
