await t('Access queues filter the full view',async()=>{await go('access');await p.click('#topbar [data-act=simple][data-v="0"]');await p.waitForTimeout(150);const a=(await p.$$('main .accb')).length;await p.click('[data-act=accq][data-v=done]');await p.waitForTimeout(150);const c=(await p.$$('main .accb')).length;await p.click('[data-act=accq][data-v=open]');await p.waitForTimeout(150);return c<a&&c>0});
await t('Access full view: picking a brand shows only its platforms',async()=>{await go('access');const bs=await p.$$eval('main .accb',e=>e.map(x=>x.dataset.id));const id=bs[bs.length-1];await p.click(`[data-act=accb][data-id="${id}"]`);await p.waitForTimeout(150);const ids=await p.$$eval('main tr[data-kind=access]',e=>e.map(x=>x.dataset.id));const on=await p.$eval('main .accb.on',e=>e.dataset.id);return on===id&&ids.length>0&&ids.every(x=>x.startsWith(id))});
await t('Access full view: find box narrows the brand list',async()=>{await go('access');const a=(await p.$$('main .accb:not([hidden])')).length;await p.fill('#acc-find','cel');await p.waitForTimeout(100);const b=await p.$$eval('main .accb:not([hidden])',e=>e.map(x=>x.innerText));await p.fill('#acc-find','');await p.evaluate(()=>document.activeElement.blur());return b.length>0&&b.length<a&&b.every(x=>/cel/i.test(x))});
await t('Light theme stays light on a dark-mode device (inputs, scrollbars)',async()=>{const q=await b.newPage({viewport:{width:1280,height:800},colorScheme:'dark'});await q.goto(u+'#access');await q.waitForTimeout(500);await q.click('#topbar [data-act=simple][data-v="0"]');await q.waitForTimeout(200);const r=await q.evaluate(()=>{const cs=getComputedStyle(document.documentElement).colorScheme;const bg=getComputedStyle(document.getElementById('acc-find')).backgroundColor;const tw=document.querySelector('.accdet .tw');return cs==='light'&&bg==='rgb(255, 255, 255)'&&tw.scrollWidth<=tw.clientWidth+1});await q.close();return r});
await t('Campaign: add, edit in panel, delete',async()=>{await go('brand-tiny-wins');await p.click('button[data-tab=tasks]');await p.click('[data-act=add-camp]');await p.fill('#n-cn','Test push');await p.click('#fbox button[type=submit]');await p.waitForTimeout(400);
  await p.click('.cbox [data-act=open][data-kind=camp]');await p.waitForTimeout(200);await p.fill('#d-name','Test push 2');await p.selectOption('#d-status','Live');await p.click('[data-act=dsave]');await p.waitForTimeout(300);const renamed=(await p.$eval('.cbox h2',e=>e.innerText))==='Test push 2';
  await p.click('.cbox [data-act=open][data-kind=camp]');await p.waitForTimeout(200);await p.click('#drawer [data-act=del]');await p.click('[data-act=mok]');await p.waitForTimeout(300);const gone=!(await p.$$eval('.camp .cn',e=>e.map(x=>x.innerText))).includes('Test push 2');return renamed&&gone});
