await t('Settings: Access setup saves',async()=>{await go('settings');await p.click('[data-act=settab][data-tab=access]');await p.fill('#a-cd','3');await p.click('#aform button[type=submit]');await p.waitForTimeout(250);await p.click('[data-act=settab][data-tab=people]');await p.click('[data-act=settab][data-tab=access]');return await p.$eval('#a-cd',e=>e.value)==='3'});
