await t('Clicking a list name opens rename',async()=>{await p.click('main .kname');await p.waitForTimeout(150);const r=await modalOpen()&&!!(await p.$('#n-ln'));await closeAll();return r});
await t('Add another list opens form',async()=>{await p.click('[data-act=kl-add]');await p.waitForTimeout(150);const r=await modalOpen();await closeAll();return r});
await t('Board due filter keeps only cards with no due date',async()=>{const a=(await p.$$('main .kc')).length;await p.selectOption('[data-act=kbf][data-k=due]','none');await p.waitForTimeout(150);const c=(await p.$$('main .kc')).length;const dated=(await p.$$('main .kc .kbg[title^="Due"]')).length;await p.click('[data-act=kbf-clear]');await p.waitForTimeout(150);return c<=a&&dated===0});
