await t('Show done cards adds done cards',async()=>{const a=(await p.$$('main .kc')).length;await p.check('[data-act=kbdone]');await p.waitForTimeout(150);const c=(await p.$$('main .kc')).length;await p.uncheck('[data-act=kbdone]');await p.waitForTimeout(150);return c>=a});
await t('Phase track: clicking a phase shows its steps',async()=>{await p.click('button[data-tab=sow]');await p.waitForTimeout(150);const n=await p.$$('.pnode');if(n.length<2)return 'one phase';await n[0].click();await p.waitForTimeout(150);const a=await p.$eval('.step .code',e=>e.textContent);await (await p.$$('.pnode'))[1].click();await p.waitForTimeout(150);const c=await p.$eval('.step .code',e=>e.textContent);return a!==c&&(await p.$$('.pnode.on')).length===1});
