await t('Card back: tag a member, then remove them',async()=>{await go('brand-bespoke/tasks');await p.waitForTimeout(200);const c=await p.$('main .kc');if(!c)return 'no cards';await c.click();await p.waitForTimeout(250);
  const n0=(await p.$$('#drawer .mem')).length;const v=await p.$eval('#mem-add',e=>[...e.options].map(o=>o.value).find(Boolean));if(!v)return 'no one to tag';await p.focus('#mem-add');await p.selectOption('#mem-add',v);await p.waitForTimeout(400);
  const n1=(await p.$$('#drawer .mem')).length;const x=(await p.$$("#drawer .memx")).pop();if(!x)return "no remove button, members "+n0+" to "+n1;await x.click();await p.waitForTimeout(400);const n2=(await p.$$('#drawer .mem')).length;await closeAll();return n1===n0+1&&n2===n0});
